def resolve(path, cwd, links):
    def split(p):
        return [c for c in p.split('/') if c not in ('', '.')]

    if path is None:
        return None

    if path.startswith('/'):
        current = '/'
        components = split(path)
    else:
        current = cwd
        components = split(path)

    remaining = components[::-1]  # stack, pop from end
    link_count = 0

    while remaining:
        comp = remaining.pop()
        if comp == '..':
            if current != '/':
                idx = current.rfind('/')
                if idx <= 0:
                    current = '/'
                else:
                    current = current[:idx]
        else:
            if current == '/':
                newpath = '/' + comp
            else:
                newpath = current + '/' + comp

            if newpath in links:
                link_count += 1
                if link_count > 8:
                    return None
                target = links[newpath]
                if target.startswith('/'):
                    base = '/'
                    target_components = split(target)
                    current = base
                else:
                    base = current  # directory containing the link
                    target_components = split(target)
                    current = base
                remaining.extend(target_components[::-1])
            else:
                current = newpath

    return current

